import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';

// Column helpers shared by the *.entity.ts files.

/** A UUID v7 primary key generated by PostgreSQL. */
export const id = () =>
	uuid()
		.primaryKey()
		.default(sql`uuidv7()`);

/** A timestamp with time zone. Add .notNull() when the value is required. */
export const timestampTz = () => timestamp({ withTimezone: true });

/** When the row was created. */
export const createdAt = () => timestampTz().notNull().defaultNow();
